examples.template:
orders.forEachIndexed { index, order ->
    MonarchButton(
        text = order.first,
        onClick = { selected = index },
        variant = if (index == selected) MonarchButtonVariant.Secondary else MonarchButtonVariant.Ghost,
    )
}
selected?.let { index ->
    val order = orders[index]
    // The peek stays beside the list, as on the web: previous and next, the position, the full record and close.
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.lg)
            .clip(MonarchTheme.shapes.lg),
    ) {
        Row(
            modifier = Modifier.padding(horizontal = MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
        ) {
            MonarchIconButton(label = "Previous", onClick = { selected = index - 1 }, enabled = index > 0, size = MonarchButtonSize.Sm) {
                MonarchIcon(SampleIcons.ChevronUp, contentDescription = null, size = MonarchIconSize.Sm)
            }
            MonarchIconButton(label = "Next", onClick = { selected = index + 1 }, enabled = index < orders.size - 1, size = MonarchButtonSize.Sm) {
                MonarchIcon(SampleIcons.ChevronDown, contentDescription = null, size = MonarchIconSize.Sm)
            }
            MonarchText(
                text = "${index + 1} of ${orders.size}",
                modifier = Modifier.weight(1f),
                style = MonarchTextStyle.Caption,
                color = MonarchTheme.colors.textMuted,
            )
            MonarchLink(text = "Open full record", onClick = { selected = null }, variant = MonarchLinkVariant.Standalone)
            MonarchIconButton(label = "Close", onClick = { selected = null }, size = MonarchButtonSize.Sm) {
                MonarchIcon(SampleIcons.Close, contentDescription = null, size = MonarchIconSize.Sm)
            }
        }
        MonarchDivider(variant = MonarchDividerVariant.Subtle)
        Column(
            modifier = Modifier.padding(MonarchTheme.spacing.space4),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
        ) {
            MonarchText(text = order.first, style = MonarchTextStyle.BodyStrong, heading = true)
            MonarchText(text = order.second, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
            Spacer(Modifier.height(MonarchTheme.spacing.space3))
            MonarchText(text = "Total " + order.third)
        }
        MonarchDivider(variant = MonarchDividerVariant.Subtle)
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(MonarchTheme.colors.bgSubtle)
                .padding(MonarchTheme.spacing.space3),
            horizontalArrangement = Arrangement.End,
        ) {
            MonarchButton(
                text = {{footer}},
                onClick = { selected = null },
                variant = MonarchButtonVariant.Primary,
                size = MonarchButtonSize.Sm,
            )
        }
    }
}

