examples.code:
@OptIn(ExperimentalMaterial3AdaptiveApi::class)
NavigableSupportingPaneScaffold(
    navigator = navigator,
    mainPane = {
        AnimatedPane {
            Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchText(text = "Invoices", style = MonarchTextStyle.Heading)
                MonarchButton(
                    text = "Preview INV-1042",
                    onClick = { scope.launch { navigator.navigateTo(SupportingPaneScaffoldRole.Supporting) } },
                )
            }
        }
    },
    supportingPane = {
        AnimatedPane {
            Surface(color = MonarchTheme.colors.bgRaised) {
                Column(
                    modifier = Modifier.padding(MonarchTheme.spacing.space4),
                    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                ) {
                    MonarchText(text = "INV-1042", style = MonarchTextStyle.Heading)
                    MonarchText(text = "Due in 5 days")
                    MonarchButton(text = "Close", onClick = { scope.launch { navigator.navigateBack() } })
                }
            }
        }
    },
)
